from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('P07','Terreno, pendenze e sintesi territoriali','Geometria raster, unità fisiche e ricampionamento di blocchi')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('P07',i,b)
m.sezione_nuova('Geometria e orientamento del raster')
p('La geometria della superficie sintetica',
'''Il progetto ricostruisce un terreno sintetico di ventiquattro righe e trenta colonne, con celle quadrate di trenta metri. L’obiettivo collega lettura del raster, calcolo delle pendenze, sintesi per zona e sensibilità al ricampionamento spaziale. La superficie liscia rende visibile la dipendenza fra celle vicine, per cui il loro numero non coincide con quello di repliche indipendenti. Il GeoTIFF conserva una georeferenziazione fittizia, che serve a esercitare il trattamento delle coordinate senza rappresentare un rilievo territoriale reale.''',tikz=d('D01',''.join(rect(.7+j*.8,1+i*.65,1.45+j*.8,1.6+i*.65,'Quantum' if (i+j)%3==0 else 'Classical') for i in range(5) for j in range(7))+n(3.7,.3,'Schema di celle con valori e posizione',w=6.8,size=11.5)+n(3.7,5.2,'Griglia effettiva: 24 × 30 celle',w=6.8,size=12)+n(3.7,6,'30 m per lato; 64,8 ha',w=6.8,size=11.5)),richiamo='La geometria determina il significato fisico delle operazioni sulla matrice.',origine='P07:1–4')
p('Valori, estensione e sistema di riferimento',
'''La lettura del GeoTIFF verifica dimensioni, risoluzione, estensione e sistema di riferimento dichiarato. Le quote del file corrispondono a quelle della tabella CSV entro la precisione di memorizzazione, ma l’ordine delle righe è opposto: il raster procede dall’alto verso il basso, mentre la matrice locale segue y crescente. Il confronto richiede quindi un’inversione esplicita delle righe. Il controllo impedisce che una matrice numericamente plausibile venga associata a posizioni capovolte, mantenendo inoltre dichiarata la natura fittizia della georeferenziazione.''',formula=r'Z^{GeoTIFF}_{r,c}\simeq Z^{locale}_{25-r,c}',destra='Il GeoTIFF dichiara UTM 32N e un’estensione costruita per l’esercizio. La compatibilità numerica con questo riferimento non dimostra una localizzazione reale e non autorizza a sovrapporlo ai punti sintetici del progetto P06.',richiamo='La corrispondenza dei valori deve essere verificata insieme all’orientamento degli assi.',origine='P07:3,5–7')
c=estratto('P07','geometria',"d <- read.csv('dati/raster_v3.csv')\nd <- d[order(d$riga,d$colonna),]\nZ <- matrix(d$quota_m,24,byrow=TRUE)\nr <- terra::rast('dati/raster_v3.tif')\nM <- as.matrix(r,wide=TRUE)\nstopifnot(nrow(r)==24,ncol(r)==30,\n all(terra::res(r)==30),\n max(abs(M-Z[24:1,]))<.001)")
p('Il confronto fra formati verifica la stessa superficie',
'''Il frammento ordina le righe del CSV prima di ricostruire la matrice, poi confronta le quote con il GeoTIFF attraverso la convenzione di orientamento esplicitata. La tolleranza di un millesimo di metro ammette la differenza dovuta alla precisione numerica del formato, mantenendo il controllo molto più stretto delle variazioni del terreno. Dimensioni e passo vengono verificati separatamente, poiché l’uguaglianza di una sequenza di valori non sarebbe sufficiente a garantire la medesima geometria territoriale.''',codice=c,richiamo='Un controllo fra formati deve specificare ordinamento, orientamento e tolleranza numerica.',origine='P07:6–7')
p('La carta delle quote e la scala metrica',
'''La superficie viene rappresentata con rapporto unitario fra gli assi e una scala cromatica continua della quota. Ogni cella conserva il proprio supporto areale di novecento metri quadrati, mentre i valori rappresentano il terreno sintetico campionato sulla griglia. La carta permette di riconoscere variazioni graduali e direzioni di cambiamento, che verranno riassunte attraverso il gradiente. La risoluzione della griglia limita le strutture rappresentabili e deve accompagnare l’interpretazione delle derivate calcolate numericamente.''',figura='P07/F01',didascalia='Quote sintetiche sulla griglia locale di trenta metri.',richiamo='Risoluzione e supporto della cella delimitano le strutture interpretabili nella superficie.',origine='P07:5–8')
m.sezione_nuova('Gradiente e pendenza fisica')
p('Le differenze centrate approssimano il gradiente',
'''Nelle celle interne, la derivata rispetto a x viene approssimata confrontando le due celle laterali, separate da sessanta metri; lo stesso procedimento viene applicato lungo y. Le differenze centrate utilizzano così una finestra locale e producono componenti del gradiente in metri per metro. Le celle del bordo vengono escluse, poiché il loro calcolo richiederebbe una regola differente o valori esterni alla griglia. Rimangono ventidue righe per ventotto colonne, pari a 616 pendenze interne.''',formula=r'g_x\simeq\frac{Z_{r,c+1}-Z_{r,c-1}}{2\Delta x},\qquad g_y\simeq\frac{Z_{r+1,c}-Z_{r-1,c}}{2\Delta y}',tikz=d('D02',rect(2.6,2.1,4.2,3.7,'Quantum')+n(3.4,2.9,r'$Z_{r,c}$',size=14)+rect(.6,2.1,2.2,3.7)+n(1.4,2.9,r'$Z_{r,c-1}$',size=12)+rect(4.6,2.1,6.2,3.7)+n(5.4,2.9,r'$Z_{r,c+1}$',size=12)+a(.7,4.5,6.1,4.5)+n(3.4,5.3,'Distanza fra i due vicini: 60 m',w=6.5,size=11.5)+n(3.7,.9,'Derivata lungo x nella cella centrale',w=6.8,size=11.5)),richiamo='Il denominatore della differenza finita è una distanza fisica, determinata dalla risoluzione.',origine='P07:8–10')
p('Angolo e percentuale derivano dalla stessa tangente',
'''La norma del gradiente esprime il rapporto fra variazione verticale e distanza orizzontale nella direzione di massima crescita. Coincidendo con la tangente della pendenza, permette di ricavarne angolo e percentuale. La percentuale è cento volte il rapporto, mentre l’angolo richiede l’arcotangente e la conversione da radianti a gradi. Un angolo di quarantacinque gradi corrisponde quindi al cento per cento, come viene verificato numericamente nel codice.''',formula=r'g=\sqrt{g_x^2+g_y^2},\qquad\theta=\arctan(g)\frac{180}{\pi}\\p_{\%}=100g=100\tan\!\left(\theta\frac{\pi}{180}\right)',figura='P07/F03',didascalia='Relazione non lineare fra gradi e percentuale; punto viola: 45° e 100%.',richiamo='L’angolo e la percentuale esprimono la stessa inclinazione attraverso scale differenti.',origine='P07:8–10')
c=estratto('P07','pendenza',"d <- read.csv('dati/raster_v3.csv')\nd <- d[order(d$riga,d$colonna),]\nZ <- matrix(d$quota_m,24,byrow=TRUE)\ngx <- (Z[2:23,3:30]-Z[2:23,1:28])/60\ngy <- (Z[3:24,2:29]-Z[1:22,2:29])/60\ng <- sqrt(gx^2+gy^2)\ngradi <- atan(g)*180/pi\nstopifnot(length(gradi)==616,\n max(abs(100*tan(gradi*pi/180)-100*g))<1e-10)")
p('Il codice conserva dominio e unità delle derivate',
'''Le porzioni della matrice vengono selezionate in modo da confrontare celle simmetriche attorno a ogni posizione interna. Il calcolo produce matrici di dimensione identica per le due derivate, delle quali si combina la norma prima della trasformazione in gradi. Il controllo inverso riconduce l’angolo alla pendenza percentuale e intercetta errori di conversione. Una prova supplementare su un piano di pendenza nota, sviluppata nel modulo M12, verifica che il metodo recuperi le componenti imposte analiticamente.''',codice=c,richiamo='Le verifiche numeriche collegano il calcolo matriciale alla definizione geometrica della pendenza.',origine='P07:9–10')
p('La carta delle pendenze riguarda soltanto l’interno',
'''Le 616 celle interne mostrano pendenze comprese fra circa 0,49 e 28,53 gradi. La rappresentazione rende riconoscibili zone di maggiore inclinazione, mantenendo il bordo escluso dal calcolo. La derivata amplifica variazioni locali e dipende dal passo e dalla regola numerica adottati; una diversa risoluzione potrebbe quindi modificare il risultato anche descrivendo lo stesso terreno generale. L’interpretazione collega la carta all’algoritmo e alla geometria, evitando di considerare ogni valore una proprietà indipendente dalla scala di osservazione.''',figura='P07/F02',didascalia='Pendenza in gradi nelle 616 celle interne.',richiamo='Una derivata raster viene interpretata rispetto a risoluzione, finestra e trattamento del bordo.',origine='P07:8–10')
m.sezione_nuova('Zone e unità della sintesi')
p('L’aggregazione produce una riga per zona',
'''La griglia è suddivisa in due zone sintetiche, A e B, ciascuna composta da 360 celle. La sintesi riunisce le quote entro ogni zona e produce una tabella con media, deviazione standard, conteggio e area. Il passaggio modifica il livello della tabella: la riga finale rappresenta una zona, mentre il conteggio delle celle descrive copertura e risoluzione. La regolarità spaziale del terreno rende improprio interpretare automaticamente le 360 celle come altrettante repliche indipendenti per un confronto inferenziale.''',figura='P07/F04',didascalia='Due zone sintetiche di 360 celle e 32,4 ettari ciascuna.',richiamo='L’unità della tabella aggregata e il numero delle repliche inferenziali devono essere dichiarati separatamente.',origine='P07:11–13')
p('Media zonale e area hanno denominatori espliciti',
'''Le celle hanno area uguale, per cui la media aritmetica coincide con la media pesata per area della rappresentazione raster. La zona A ha quota media circa 986,025 metri e la zona B circa 1044,597 metri; le deviazioni standard descrittive sono circa 46,018 e 27,345 metri. L’area di ciascuna zona è 32,4 ettari. Con celle di area diversa o copertura incompleta, la ponderazione e il denominatore richiederebbero una formulazione ulteriore, coerente con la quantità territoriale da rappresentare.''',formula=r'\overline z_A=\frac{\sum_{i\in A}a_i z_i}{\sum_{i\in A}a_i},\qquad a_i=900\ \mathrm{m^2}\\\mathrm{area}(A)=360\times900/10^4=32{,}4\ \mathrm{ha}',destra='Le due medie descrivono le zone definite nella superficie disponibile. Un intervallo inferenziale sulla differenza richiederebbe un processo generatore, un disegno di osservazione e una rappresentazione della dipendenza, oltre alle sole statistiche zonali.',richiamo='La sintesi territoriale richiede pesi coerenti con area, copertura e supporto della variabile.',origine='P07:12–13')
p('La dispersione spaziale delle quote',
'''I boxplot confrontano la distribuzione delle quote nelle due zone, rendendo visibili differenze di livello e dispersione. Le scatole riassumono valori delle celle e non costituiscono intervalli di confidenza delle medie zonali. La maggiore variabilità della zona A descrive la superficie campionata, senza implicare da sola maggiore incertezza strumentale. La distinzione fra eterogeneità territoriale, errore di misura e incertezza inferenziale rimane essenziale quando una carta viene trasformata in una tabella di sintesi.''',figura='P07/F05',didascalia='Distribuzioni delle quote nelle due zone; scatole descrittive delle celle.',richiamo='La variabilità nello spazio e l’incertezza su una media sono quantità differenti.',origine='P07:11–13,17')
m.sezione_nuova('Ricampionamento e limiti della conclusione')
p('La struttura locale nei blocchi',
'''Il terreno viene suddiviso in dodici blocchi contigui, ciascuno di sei righe per dieci colonne. La media di ogni blocco riassume sessanta celle e viene utilizzata come unità del ricampionamento. Poiché i blocchi hanno la stessa area, la media delle dodici medie coincide con quella delle 720 celle, circa 1015,311 metri. La scelta conserva una struttura locale più ampia rispetto al ricampionamento delle singole celle, pur lasciando possibile dipendenza fra blocchi confinanti.''',figura='P07/F06',didascalia='Dodici blocchi di 6 × 10 celle, identificati sulla superficie.',richiamo='La dimensione dei blocchi deve essere discussa rispetto alla scala della dipendenza spaziale.',origine='P07:14–16')
p('La replica estrae dodici medie di blocco',
'''Ogni replica seleziona con reinserimento dodici medie di blocco e ne calcola la media. La procedura produce 1999 repliche e conserva il piano degli indici utilizzati, rendendo ricostruibile ogni estrazione. Il riferimento tratta i blocchi osservati come unità scambiabili, ipotesi che richiede cautela su una superficie liscia e con struttura territoriale. L’esercizio viene interpretato come sensibilità condizionata allo schema, mentre un intervallo con validità generale richiederebbe una giustificazione probabilistica della disposizione e della dimensione dei blocchi.''',formula=r'\overline z_b=\frac1{60}\sum_{i\in b}z_i,\qquad\overline z^{*}=\frac1{12}\sum_{r=1}^{12}\overline z_{I_r}',tikz=d('D04',rect(.6,.8,6.8,2.2)+n(3.7,1.5,'Dodici blocchi osservati',w=5.8,size=13)+a(3.7,2.5,3.7,3.2,'Quantum')+rect(.6,3.5,6.8,4.9,'Quantum')+n(3.7,4.2,'Dodici estrazioni con reinserimento',w=5.8,size=12)+n(3.7,5.8,'Le molteplicità cambiano fra le repliche.',w=6.7,size=11.5)),richiamo='L’unità ricampionata esprime un’ipotesi sulla componente di variabilità rappresentata.',origine='P07:14–16')
p('L’intervallo descrive il riferimento adottato',
'''I quantili 2,5% e 97,5% delle medie ricampionate sono circa 990,284 e 1038,958 metri. L’ampiezza riflette la variabilità fra i dodici blocchi osservati sotto la procedura definita, mentre la media della superficie completa è già calcolabile esattamente dai valori disponibili. Il ricampionamento non misura automaticamente l’errore di quella media finita. La distinzione diventa particolarmente rilevante se si vuole estendere l’argomento a un processo territoriale, ad altre aree o a una raccolta incompleta di osservazioni.''',figura='P07/F07',didascalia='Distribuzione di 1999 medie ricampionate; linee viola: quantili percentili.',richiamo='L’incertezza richiede un bersaglio probabilistico; la media di un raster completo è una quantità finita osservata.',origine='P07:16–18')
p('Consegna e interpretazione territoriale',
'''La relazione conserva audit del GeoTIFF, confronto dell’orientamento, formula delle pendenze, statistiche zonali, disposizione dei blocchi e distribuzione ricampionata. L’esercizio richiede di spiegare perché quarantacinque gradi corrispondano al cento per cento e perché 360 celle non garantiscano 360 repliche indipendenti. Una discussione finale individua quale bersaglio potrebbe giustificare un’inferenza oltre la superficie completa disponibile. La conclusione collega ogni grandezza al supporto spaziale, alle unità e alla natura sintetica dei dati.''',destra='R/P07_figure.R integra le attività M12_N03, N10, N15 e N17. Il macroprogetto utilizza 1999 repliche e conserva i piani; il laboratorio originario mantiene il proprio esempio ridotto. Il GeoTIFF e il CSV rimangono accompagnati dai rispettivi metadati e dalle verifiche di orientamento.',richiamo='Il significato fisico e inferenziale dei risultati dipende dalla geometria e dall’unità della sintesi.',fonti='Raccordo M12; documentazione terra',origine='P07:17–20')
m.salva()
